# ---------------------------------------------------------------- data
def build_data():
    here = os.path.dirname(os.path.abspath(__file__))
    mat = {'outline': [], 'fill': []}
    cur = None
    for l in open(os.path.join(here, 'icons-material.txt')).read().split('\n'):
        l = l.strip()
        if not l or l.startswith('#'):
            continue
        if l in ('[outline]', '[fill]'):
            cur = l[1:-1]
            continue
        mat[cur].append(l)
    src = open(os.path.join(here, '..', '..', 'components', 'icon-picker', 'icon-picker-data.js')).read()
    names = set(re.findall(r'\["([a-z0-9_]+)",', src))

    def lig(n):
        n = re.sub(r'(_filled|_fill)$', '', n.lower())
        return {'favourite': 'favorite'}.get(n, n)
    custom = []
    for l in open(os.path.join(here, 'icons-custom.txt')).read().split('\n'):
        if not l.strip():
            continue
        r = l.split('|', 3)
        if '@' in r[0]:   # name@40: a hand-drawn variant for that size (Figma Large), used by the library at 40px
            base, size = r[0].split('@')
            for c in custom:
                if c[0] == base:
                    c.append({size: [r[2], r[3]]})
            continue
        custom.append(r)
    nog = [n for n in mat['outline'] + mat['fill'] if lig(n) not in names]
    data = {'outline': [[n, lig(n)] for n in mat['outline']], 'fill': [[n, lig(n)] for n in mat['fill']], 'custom': custom}
    out = os.path.join(here, '..', '..', 'components', 'icon-library', 'icon-library-data.js')
    os.makedirs(os.path.dirname(out), exist_ok=True)
    open(out, 'w').write('/* ECO icon library data, generated by eco-design-system/gen/gen_icon.py. outline/fill: [figmaName, fontLigature]; custom: [name, group, viewBox, svgInner] */\nwindow.ECO_ICON_LIB=' + json.dumps(data, ensure_ascii=False, separators=(',', ':')) + ';\n')
    print('wrote', out, len(custom), 'custom;', 'no Material glyph for:', nog)


